package probe

import (
 "context"
 "net"
 "net/http"
 "net/http/httptest"
 "testing"
 "time"
)

func TestDialOverride(t *testing.T) {
 received := make(chan struct{}, 1)
 server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
  received <- struct{}{}
  <-r.Context().Done()
 }))
 defer server.Close()
 transport := http.DefaultTransport.(*http.Transport).Clone()
 transport.Proxy = nil
 transport.DialContext = func(ctx context.Context, network, addr string) (net.Conn, error) {
  return (&net.Dialer{}).DialContext(ctx, network, server.Listener.Addr().String())
 }
 defer transport.CloseIdleConnections()
 client := &http.Client{Timeout: 200*time.Millisecond, Transport: http.DefaultTransport}
 err := (Service{HTTP: client}).Check(context.Background())
 if err == nil { t.Fatal("want error from stalled endpoint") }
}

